import{mix}from './world.js';
const clamp=n=>Math.max(0,Math.min(100,n));
// Four daily periods; intake is an actual bounded reduction, not a fixed daily subsidy.
// Values are game need scores, not calories, liters, or clinical recommendations.
export function physiologyStep(s,log){const n=s.needs,w=s.worldModel,young=s.day<55,kg=s.appearance.adultKg,energy=w.traits.energy,heat=s.world==='heat',sick=!!s.medical.episode;const activity=s.behavior?.activity??((sick||['recovery','rehabilitation'].includes(s.clinical?.active?.stage))?.25:.5+energy/100);const variation=(mix(s.seed+s.day,811)%31)/100;const access=s.environmentModel?.access||{food:w.resource,water:w.care,medical:w.care};const caregiver=s.humans?.find(h=>h.id===s.caregiverId);const available=Math.min(.98,(s.home==='street'?.25:.55)+access.food/250+(caregiver?caregiver.care/700:0));const milkAvailable=young&&(w.origin.mother||w.care>=20);const mealPhases=young?[0,1,2,3]:s.day%2?[1,3]:[0,2];let eaten=0,drunk=0,phaseHistory=[];
for(let period=0;period<4;period++){const demand=(young?3.5:4+activity*2+(kg<10?1:0))*(.85+variation);n.hunger=clamp(n.hunger+demand+(sick?1:0));n.thirst=clamp(n.thirst+(young?2.5:3+activity)+(heat?3:0));const foodPresent=milkAvailable||mix(s.seed+s.day,820+period)%100<available*100;const ableToEat=!sick||mix(s.seed+s.day,840+period)%100<65;if(mealPhases.includes(period)&&foodPresent&&ableToEat){const portion=Math.min(n.hunger*.62,young?25:20+kg*.25+access.food/10);n.hunger=clamp(n.hunger-portion);eaten+=portion;if(young){const hydration=n.thirst*.75;n.thirst-=hydration;drunk+=hydration}}const waterPresent=young?milkAvailable:mix(s.seed+s.day,860+period)%100<Math.min(98,(s.home==='street'?25+access.water*.65:50+access.water*.48));if(!young&&waterPresent&&n.thirst>=12+mix(s.seed+s.day,880+period)%9){const amount=n.thirst*.72;n.thirst-=amount;drunk+=amount}phaseHistory.push({period,hunger:Math.round(n.hunger*10)/10,thirst:Math.round(n.thirst*10)/10});}
n.version=2;n.foodIntake=Math.round(eaten*10)/10;n.waterIntake=Math.round(drunk*10)/10;n.feeding=young?'젖·보조 급여':'그릇 또는 생활권 먹이';n.lastDay=s.day;n.phases=phaseHistory;n.fatigue=clamp(n.fatigue+(sick?3:-2)+(s.stress>65?2:0)+activity*.3);n.happiness=clamp(.6*s.comfort+.25*(100-s.stress)+.15*(s.home==='family'?s.familyBond:s.dogBond));n.strain=n.hunger>85||n.thirst>85?(n.strain||0)+1:0;if(n.strain===3)log(s,'needs-warning',n.thirst>85?'물을 충분히 마시지 못한 날이 이어진다. 몸이 무겁고 움직임이 줄었다.':'먹이가 부족한 날이 이어진다. 한 번에 멀리 움직이지 않고 쉬는 시간이 늘었다.');if(n.strain>3)s.health=clamp(s.health-.2);}
